# Adapted from Schuture/OpenAI-Interview-Notes (code under the MIT License).
# This limiter passes a light smoke test but breaks the rules. Fix it; keep the constructor and allow().
import time
from collections import defaultdict, deque


class RateLimiter:
    def __init__(self, rules, clock=time.time, checkpoint=lambda: None):
        self.rules = list(rules)  # (max_requests, period_seconds) pairs; this code assumes the last is the longest
        self.clock = clock
        self.checkpoint = checkpoint
        self.logs = defaultdict(lambda: [deque() for _ in self.rules[:-1]])  # user_id -> admitted times per rule
        self.buckets = {}  # user_id -> (window number, count) for the last rule, to save memory

    def _admit(self, log, now, limit, period):
        while log and now - log[0] >= period:
            log.popleft()
        if len(log) >= limit:
            return False
        log.append(now)
        return True

    def allow(self, user_id):
        now = self.clock()
        for (limit, period), log in zip(self.rules, self.logs[user_id]):
            if not self._admit(log, now, limit, period):
                return False
        limit, period = self.rules[-1]
        window = int(now // period)
        start, count = self.buckets.get(user_id, (window, 0))
        if start != window:
            count = 0
        self.checkpoint()
        if count >= limit:
            return False
        self.buckets[user_id] = (window, count + 1)
        return True

