        return self.token_ids[len(self.prompt):]

    def is_stopped(self):
        """True once max_tokens tokens were generated or the last one is EOS_TOKEN."""
        return len(self.generated) >= self.max_tokens or self.token_ids[-1] == EOS_TOKEN


